``` C
void OSSL_sleep(uint64_t millis)
{
/* Special cases here */
#else
    unsigned int s = (unsigned int)(millis / 1000);
    useconds_t us = (useconds_t)(millis % 1000);

    sleep(s);
    usleep(us);
#endif
}
